def is_nested(string):
    stack = []
    nested = False

    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                stack.pop()
                if len(stack) > 0:  # More than one '[' means we have a nested bracket
                    nested = True

    return nested

